def add_cover(pdf, page_num):
    """Portada"""
    pdf.setPageSize((page_width, page_height))
    pdf.setFillColor(HexColor("#2a3a2d"))
    pdf.rect(0, 0, page_width, page_height, fill=1, stroke=0)

    # Título
    pdf.setFont("Helvetica-Bold", 52)
    pdf.setFillColor(white)
    pdf.drawCentredString(page_width/2, page_height - 100, "Bioartesa")

    # Subtítulo
    pdf.setFont("Helvetica", 24)
    pdf.drawCentredString(page_width/2, page_height - 160, "Welcome Box Collection")

    # Información
    pdf.setFont("Helvetica", 11)
    pdf.drawCentredString(page_width/2, page_height - 220, "Obrador ecológico")
    pdf.drawCentredString(page_width/2, page_height - 240, "Castilléjar, Granada")
    pdf.drawCentredString(page_width/2, page_height - 280, "2026")

    return page_num + 1

def add_product_pages(pdf, products, page_num):
    """Páginas de productos: 6 por página (2 columnas × 3 filas)"""
    cols, rows = 2, 3
    products_per_page = cols * rows

    for page_idx, i in enumerate(range(0, len(products), products_per_page)):
        pdf.showPage()
        pdf.setPageSize((page_width, page_height))
        pdf.setFillColor(COLOR_BG_LIGHT)
        pdf.rect(0, 0, page_width, page_height, fill=1, stroke=0)

        page_products = products[i:i+products_per_page]

        # Espaciado
        col_width = (page_width - 2*margin) / cols
        row_height = (page_height - 2*margin) / rows

        for idx, product in enumerate(page_products):
            row = idx // cols
            col = idx % cols

            x = margin + col * col_width
            y = page_height - margin - (row + 1) * row_height

            # Rectángulo de fondo del producto
            photo_height = row_height * 0.6

            # Fondo oscuro para la foto
            pdf.setFillColor(COLOR_BG_DARK)
            pdf.rect(x + 0.3*cm, y + row_height - photo_height - 0.3*cm,
                    col_width - 0.6*cm, photo_height, fill=1, stroke=0)

            # Cargar imagen si existe
            img_path = f"/Users/fernandoiriarte/bioartesa-catalogo/{product['img']}"
            if os.path.exists(img_path):
                try:
                    img = Image.open(img_path)
                    # Redimensionar imagen proporcionalmente
                    aspect = img.width / img.height
                    if aspect > 1:
                        img_w = photo_height * 0.8 * aspect
                        img_h = photo_height * 0.8
                    else:
                        img_w = photo_height * 0.8
                        img_h = photo_height * 0.8 / aspect

                    # Centrar en el recuadro
                    img_x = x + (col_width - img_w) / 2
                    img_y = y + row_height - photo_height + (photo_height - img_h) / 2

                    # Dibujar imagen
                    pdf.drawImage(img_path, img_x, img_y, width=img_w, height=img_h, mask='auto')
                except Exception as e:
                    print(f"Error cargando {img_path}: {e}")

            # Información del producto
            text_y = y + row_height - photo_height - 0.4*cm

            # Nombre
            pdf.setFont("Helvetica-Bold", 10)
            pdf.setFillColor(COLOR_TEXT)
            name_text = product["nombre"][:50]
            pdf.drawString(x + 0.2*cm, text_y, name_text)

            # Precio y tags
            pdf.setFont("Helvetica", 8)
            price_text = f"€{product['precio']:.2f}"
            pdf.drawString(x + 0.2*cm, text_y - 0.35*cm, price_text)

            # Badges
            tags = "BIO"
            if product["sinGluten"]:
                tags += " | SG"
            if product["vegano"]:
                tags += " | VEG"
            pdf.setFont("Helvetica", 7)
            pdf.drawString(x + 0.2*cm, text_y - 0.6*cm, tags)

        page_num += 1

    return page_num

def add_back_cover(pdf, page_num):
    """Contraportada"""
    pdf.showPage()
    pdf.setPageSize((page_width, page_height))
    pdf.setFillColor(COLOR_BG_DARK)
    pdf.rect(0, 0, page_width, page_height, fill=1, stroke=0)

    pdf.setFont("Helvetica", 12)
    pdf.setFillColor(white)

    y_start = page_height - 150
    pdf.drawCentredString(page_width/2, y_start, "Bioartesa 2012 S.L.")
    pdf.drawCentredString(page_width/2, y_start - 30, "Castilléjar, Granada")
    pdf.drawCentredString(page_width/2, y_start - 80, "Distribuido por")
    pdf.drawCentredString(page_width/2, y_start - 110, "Chains of Brains · Argón 70 S.L.")
    pdf.drawCentredString(page_width/2, y_start - 160, "bioartesa.es")

    return page_num + 1

# Generar PDF
pdf = canvas.Canvas("/Users/fernandoiriarte/bioartesa-catalogo/bioartesa-welcome-box.pdf", pagesize=(page_width, page_height))
page_num = 1

page_num = add_cover(pdf, page_num)
page_num = add_product_pages(pdf, VALID_PRODUCTS, page_num)
page_num = add_back_cover(pdf, page_num)

pdf.save()
print(f"PDF generado: ~/bioartesa-catalogo/bioartesa-welcome-box.pdf")
